-- ============================================================
-- Módulo Contabilidad — Import inicial del plan de cuentas (empresa_id = 1)
-- ============================================================
-- Generado a partir de la data legacy suministrada. Se EXCLUYERON las
-- cuentas subsidiarias de proveedores (hijas de 'PROVEEDORES' id=54 y
-- 'PROVEEDORES LOCALES' id=56 en la data origen), 74 filas en total:
--   55, 57, 152, 153, 154, 155, 156, 157, 158, 159, 160, 161, 162, 163, 164, 165, 166, 167, 168, 169, 17
--   0, 171, 172, 173, 175, 209, 210, 211, 212, 213, 214, 215, 216, 218, 219, 220, 221, 222, 223, 225, 22
--   6, 230, 241, 242, 243, 244, 245, 246, 247, 249, 251, 252, 253, 254, 255, 256, 257, 258, 259, 260, 26
--   1, 262, 263, 264, 317, 319, 320, 321, 324, 328, 330, 331, 333, 336
-- Los grupos padre PROVEEDORES / PROVEEDORES LOCALES SÍ se insertan
-- (son categorías del catálogo, no cuentas de proveedores individuales).
--
-- IMPORTANT: ejecutar create_contabilidad_catalogo_cuentas.sql PRIMERO
-- (siembra mc_tipo_cuenta con ids 1..6 en el orden Activo,Pasivo,Capital,
-- Ingreso,Costo,Gasto — el mismo orden usado por tipo_cuenta_id abajo).

BEGIN;


-- Alinear la secuencia IDENTITY de la PK con el mayor id insertado explícitamente.
SELECT setval(pg_get_serial_sequence('contabilidad.mc_cuenta', 'id'), (SELECT MAX(id) FROM contabilidad.mc_cuenta), true);

COMMIT;

